    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
a=G['Demo pair 1 input']; b=G['Demo pair 1 output']
a2=G['Demo pair 2 input']; o2=G['Demo pair 2 output']
T=G['Test input']
from collections import deque
def cc(g):
    H=len(g); W=len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=0 and not seen[r][c]:
                q=deque([(r,c)]); seen[r][c]=True; cells=[]
                while q:
                    x,y=q.popleft(); cells.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            nx,ny=x+dx,y+dy
                            if 0<=nx<H and 0<=ny<W and g[nx][ny]!=0 and not seen[nx][ny]:
                                seen[nx][ny]=True; q.append((nx,ny))
                out.append(cells)
    return out
def bbox(cells):
    rs=[x for x,_ in cells]; cs=[y for _,y in cells]
    return min(rs),max(rs),min(cs),max(cs)
def solve(g):
    res=[row[:] for row in g]
    comps=cc(g)
    def isframe(comp):
        r0,r1,c0,c1=bbox(comp)
        per=(r1-r0+1)*2+(c1-c0+1)*2-4
        return len(comp)==per and r0<r1 and c0<c1
    F={i for i,comp in enumerate(comps) if isframe(comp)}
    frames=[(g[comps[i][0][0]][comps[i][0][1]],bbox(comps[i])) for i in F]
    noises=[(i,g[comps[i][0][0]][comps[i][0][1]],set(comps[i])) for i in range(len(comps)) if i not in F]
    for i,u_,n_ in noises:
        for r,c in n_: res[r][c]=0
    for v,(r0,r1,c0,c1) in frames:
        bc_rows=set(range(r0,r1+1)); bc_cols=set(range(c0,c1+1))
        corners=[(r0,c0),(r0,c1),(r1,c0),(r1,c1)]
        best=None
        for i,u_,n_ in noises:
            for (rr,cc_) in n_:
                if rr not in bc_rows and cc_ not in bc_cols: continue
                m=min(max(abs(rr-cr_),abs(cc_-cs)) for cr_,cs in corners)
                if best is None or m<best[0] or (m==best[0] and u_<=best[1]):
                    best=(m,u_)
        fill=best[1]
        p=(r0+c0)%2
        for r in range(r0+1,r1):
            for c in range(c0+1,c1):
                if (r+c)%2==p: res[r][c]=fill
    return res
print('demo1:',solve(a)==b,'demo2:',solve(a2)==o2)
o=solve(T)
for r in o: print(''.join(map(str,r)))
print(json.dumps(o))

