    return min(rs),max(rs),min(cs),max(cs)
def solve(g):
    res=[row[:] for row in g]
    comps=cc(g)
    def isframe(comp):
        r0,r1,c0,c1=bbox(comp)
        per=(r1-r0+1)*2+(c1-c0+1)*2-4
        return len(comp)==per and r0<r1 and c0<c1
    F={i for i,comp in enumerate(comps) if isframe(comp)}
    noise_cells={}  # position -> color
    borders={}      # frame color -> list of its border pixel coords
    for i,comp in enumerate(comps):
        v=g[comp[0][0]][comp[0][1]]
        if isframe(comp):
            r0,r1,c0,c1=bbox(comp)
            for rr in range(r0,r1+1):
                for cc in (c0,c1):
                    if (rr,cc) in comp: borders.setdefault(v,[]).append((rr,cc))
                for cc in range(c0,c1+1):
                    if (r0,cc) in comp or (r1,cc) in comp:
                        pass
            # add all non-corner border cells
            for rr in range(r0,r1+1):
                for cc in range(c0,c1+1):
                    if (rr,cc) not in comp:
                        borders[v].append((rr,cc))
        else:
            for (rr,cc) in comp: noise_cells[(rr,cc)]=v
    def cheb(p,border):
        rr,cc=p
        best=10**9
        for pr,pb in border:
            d=max(abs(rr-pr),abs(cc-pb))
            if d<best: best=d
        return best
    frames=[(g[i][comps[i][0][0]][comps[i][0][1]],bbox(comps[i])) for i in F]
    for r0,r1,c0,c1,_ in [(bb[0],bb[1],bb[2],bb[3]) for bb in [frames_[1][1] for frames_ in [(None,v,boxes) ]]]:
        pass
    # collect candidate fill per frame: noise pixels, Chebyshev to ANY border pixel of any frame (global, including opposite)
    cand={}
    for v,(r0,r1,c0,c1) in frames:
        # border pixels of THIS frame
        bor={}; 
        for rr in range(r0,r1+1): bor[rr]={c0,c1}
        for cc in range(c0,c1+1): bor[c0]={r0,r1}; bor[c1]={r0,r1}
        best=(10**9,None)
        for (rr,cc),col in noise_cells.items():
            m=min(max(abs(rr-bpr),abs(cc-bpc)) for bpr in {r0,r1} for bpc in {c0,c1})
            if m<best[0] or (m==best[0] and col<best[1]):
                best=(m,col)
        cand[v]=best
    for v,(r0,r1,c0,c1) in frames:
        fill=cand[v][1]
        p=(r0+c0)%2
        for r in range(r0+1,r1):
            for c in range(c0+1,c1):
                if (r+c)%2==p: res[r][c]=fill
        # erase stray noise outside frames
    for (rr,cc),col in noise_cells.items():
        r0,r1,c0,c1=None
        ok=False
        for v,(fr0,fr1,frc0,frc1) in frames:
            if fr0<=rr<=fr1 and frc0<=cc<=frc1: ok=True; break
        if not ok: res[rr][cc]=0
    return res
